import { setTimeout as sleep } from 'node:timers/promises';
import { initSchema, nowIso, openDatabase, writeHeartbeat, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
initSchema(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const stmts = {
  recover: db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE status = 'running'"),
  nextQueued: db.prepare("SELECT id FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1"),
  claim: db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?"),
  byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  progress: db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?'),
  requeue: db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ),
  fail: db.prepare(
    "UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ?",
  ),
  complete: db.prepare(
    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
  ),
};

/** Runs `fn` inside BEGIN IMMEDIATE ... COMMIT, rolling back if it throws. Never awaits inside. */
function inTransaction<T>(fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const value = fn();
    db.exec('COMMIT');
    return value;
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction was already closed by the failure
    }
    throw e;
  }
}

/** Claims the oldest ready queued job, marking it running. Returns its id, or undefined if none is ready. */
function claimNext(): string | undefined {
  return inTransaction(() => {
    const row = stmts.nextQueued.get(Date.now()) as { id: string } | undefined;
    if (!row) return undefined;
    stmts.claim.run(nowIso(), row.id);
    return row.id;
  });
}

function requeue(id: string): void {
  stmts.requeue.run(Date.now(), nowIso(), id);
}

/** Processes one attempt of a job. Each step takes STEP_MS; progress is written after each step. */
async function runAttempt(id: string): Promise<void> {
  const job = stmts.byId.get(id) as JobRow;
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return requeue(id);
    if (attempt >= MAX_ATTEMPTS) {
      stmts.fail.run(nowIso(), id);
    } else {
      stmts.requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return requeue(id);
    stmts.progress.run(step, nowIso(), id);
  }
  stmts.complete.run(job.input.toUpperCase(), nowIso(), id);
}

function writeHeartbeatSafely(lastSeen?: number): void {
  try {
    writeHeartbeat(db, lastSeen);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}

// Only one worker runs, so any row still marked running was orphaned by a previous crash.
const recovered = stmts.recover.run(Date.now(), nowIso());
if (recovered.changes > 0) console.log(`recovered ${recovered.changes} interrupted job(s)`);

writeHeartbeatSafely();
const heartbeat = setInterval(() => writeHeartbeatSafely(), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  let id: string | undefined;
  try {
    id = claimNext();
  } catch (e) {
    console.error('claim failed:', e);
    await sleep(IDLE_POLL_MS);
    continue;
  }
  if (id === undefined) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(id);
  } catch (e) {
    // The job stays running here and is recovered on the next worker start.
    console.error(`job ${id} failed unexpectedly:`, e);
  }
}

clearInterval(heartbeat);
writeHeartbeatSafely(0);
db.close();
console.log('worker stopped');
process.exit(0);

