import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { initSchema, nowIso, openDatabase, readHeartbeat, rowToJob, type JobRow } from './db.ts';

const db = openDatabase();
initSchema(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 1024 * 1024;
const WORKER_LIVENESS_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const stmts = {
  heartbeat: db.prepare('SELECT last_seen FROM worker_heartbeat WHERE id = 1'),
  listJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  jobByKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  insertJob: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
       result_output, error, idempotency_key, payload, next_run_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, ?)`,
  ),
};

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'Not found');
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed');
}

function serveUi(res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

function health(res: ServerResponse): void {
  const lastSeen = (stmts.heartbeat.get() as { last_seen: number } | undefined)?.last_seen;
  const up = lastSeen !== undefined && lastSeen > 0 && Date.now() - lastSeen < WORKER_LIVENESS_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function listJobs(res: ServerResponse): void {
  const rows = stmts.listJobs.all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(rowToJob) });
}

function getJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    return notFound(res);
  }
  const row = stmts.jobById.get(id) as unknown as JobRow | undefined;
  if (!row) return sendError(res, 404, 'not_found', 'Job not found');
  send(res, 200, rowToJob(row));
}

/** Reads the whole body. Resolves to null if it exceeds the size cap (the rest is discarded). */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (header === undefined) return false;
  const mediaType = header.split(';')[0]!.trim().toLowerCase();
  return mediaType === 'application/json' || /^[a-z0-9.+-]+\/[a-z0-9.+-]+\+json$/.test(mediaType);
}

function isIntegerInRange(value: unknown, min: number, max: number): boolean {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Validates the submitted fields. Returns the fields with defaults applied, or the errors. */
function validateJob(
  body: Record<string, unknown>,
): { ok: true; input: string; steps: number; failAttempts: number } | { ok: false; fields: FieldError[] } {
  const fields: FieldError[] = [];

  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  const { input, steps, failAttempts } = body;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'must be a string of 1 to 1000 characters that is not only whitespace' });
  }

  if (steps !== undefined && !isIntegerInRange(steps, 1, 20)) {
    fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  }
  if (failAttempts !== undefined && !isIntegerInRange(failAttempts, 0, 5)) {
    fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  }

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  return {
    ok: true,
    input,
    steps: steps === undefined ? 5 : (steps as number),
    failAttempts: failAttempts === undefined ? 0 : (failAttempts as number),
  };
}

function replayOrConflict(res: ServerResponse, existing: JobRow, payload: string): void {
  if (existing.payload === payload) return send(res, 200, rowToJob(existing));
  sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload');
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const keyHeader = req.headers['idempotency-key'];
  const keyErrors: FieldError[] =
    keyHeader !== undefined && !IDEMPOTENCY_KEY_RE.test(keyHeader)
      ? [{ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' }]
      : [];
  const invalid = (fields: FieldError[]) => sendError(res, 400, 'invalid_request', 'Invalid request', [...fields, ...keyErrors]);

  if (!isJsonContentType(req.headers['content-type'])) {
    return invalid([{ field: 'body', message: 'Content-Type must be application/json' }]);
  }

  const text = await readBody(req);
  if (text === null) return invalid([{ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` }]);

  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return invalid([{ field: 'body', message: 'body must be valid JSON' }]);
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return invalid([{ field: 'body', message: 'body must be a JSON object' }]);
  }

  const result = validateJob(parsed as Record<string, unknown>);
  if (!result.ok) return invalid(result.fields);
  if (keyErrors.length > 0) return invalid([]);

  const { input, steps, failAttempts } = result;
  const payload = JSON.stringify({ input, steps, failAttempts });
  const key = keyHeader ?? null;

  if (key !== null) {
    const existing = stmts.jobByKey.get(key) as unknown as JobRow | undefined;
    if (existing) return replayOrConflict(res, existing, payload);
  }

  const id = randomUUID();
  const now = nowIso();
  try {
    stmts.insertJob.run(id, input, steps, failAttempts, key, payload, Date.now(), now, now);
  } catch (e) {
    // The UNIQUE constraint on idempotency_key catches a race that the lookup above cannot see.
    const existing = key !== null && e instanceof Error && /UNIQUE/.test(e.message) ? (stmts.jobByKey.get(key) as unknown as JobRow | undefined) : undefined;
    if (existing) return replayOrConflict(res, existing, payload);
    throw e;
  }

  send(res, 201, rowToJob(stmts.jobById.get(id) as unknown as JobRow));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') return method === 'GET' ? serveUi(res) : methodNotAllowed(res);
  if (pathname === '/health') return method === 'GET' ? health(res) : methodNotAllowed(res);
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res);
  }
  const match = JOB_PATH_RE.exec(pathname);
  if (match) return method === 'GET' ? getJob(res, match[1]!) : methodNotAllowed(res);
  notFound(res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error');
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  setTimeout(() => process.exit(0), 2000).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

