13	let stopping = false;
14	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
15	  process.on(signal, () => {
16	    stopping = true;
17	  });
18	}
19	
20	const stmts = {
21	  recover: db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE status = 'running'"),
22	  nextQueued: db.prepare("SELECT id FROM jobs WHERE status = 'queued' AND next_run_at <= ? ORDER BY seq ASC LIMIT 1"),
23	  claim: db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?"),
24	  byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
25	  progress: db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?'),
26	  requeue: db.prepare(
27	    "UPDATE jobs SET status = 'queued', progress_completed = 0, next_run_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
28	  ),
29	  fail: db.prepare(
30	    "UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ?",
31	  ),
32	  complete: db.prepare(
33	    "UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?",
34	  ),
35	};
36	
37	/** Runs `fn` inside BEGIN IMMEDIATE ... COMMIT, rolling back if it throws. Never awaits inside. */
38	function inTransaction<T>(fn: () => T): T {
39	  db.exec('BEGIN IMMEDIATE');
40	  try {
41	    const value = fn();
42	    db.exec('COMMIT');
43	    return value;
44	  } catch (e) {
45	    try {
46	      db.exec('ROLLBACK');
47	    } catch {
48	      // the transaction was already closed by the failure
49	    }
50	    throw e;
51	  }
52	}
53	
54	/** Claims the oldest ready queued job, marking it running. Returns its id, or undefined if none is ready. */
55	function claimNext(): string | undefined {
56	  return inTransaction(() => {
57	    const row = stmts.nextQueued.get(Date.now()) as { id: string } | undefined;
58	    if (!row) return undefined;
59	    stmts.claim.run(nowIso(), row.id);
60	    return row.id;
61	  });
62	}
63	
64	function requeue(id: string): void {
65	  stmts.requeue.run(Date.now(), nowIso(), id);
66	}
67	
68	/** Processes one attempt of a job. Each step takes STEP_MS; progress is written after each step. */
69	async function runAttempt(id: string): Promise<void> {
70	  const job = stmts.byId.get(id) as unknown as JobRow;
71	  const attempt = job.attempts;
72	
73	  if (attempt <= job.fail_attempts) {
74	    // Simulated transient failure at the first step, before any progress.
75	    await sleep(STEP_MS);
76	    if (stopping) return requeue(id);
77	    if (attempt >= MAX_ATTEMPTS) {
78	      stmts.fail.run(nowIso(), id);
79	    } else {
80	      stmts.requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), id);
81	    }
82	    return;
83	  }
84	
85	  for (let step = 1; step <= job.steps; step++) {
86	    await sleep(STEP_MS);
87	    if (stopping) return requeue(id);
88	    stmts.progress.run(step, nowIso(), id);
89	  }
90	  stmts.complete.run(job.input.toUpperCase(), nowIso(), id);
91	}
92	
93	function writeHeartbeatSafely(lastSeen?: number): void {
94	  try {
95	    writeHeartbeat(db, lastSeen);
96	  } catch (e) {
97	    console.error('heartbeat failed:', e);
98	  }
99	}
100	
101	// Only one worker runs, so any row still marked running was orphaned by a previous crash.
102	const recovered = stmts.recover.run(Date.now(), nowIso());
103	if (recovered.changes > 0) console.log(`recovered ${recovered.changes} interrupted job(s)`);
104	
105	writeHeartbeatSafely();
106	const heartbeat = setInterval(() => writeHeartbeatSafely(), HEARTBEAT_MS);
107	
108	console.log('worker started');
109	while (!stopping) {
110	  let id: string | undefined;
111	  try {
112	    id = claimNext();
113	  } catch (e) {
114	    console.error('claim failed:', e);
115	    await sleep(IDLE_POLL_MS);
116	    continue;
117	  }
118	  if (id === undefined) {
119	    await sleep(IDLE_POLL_MS);
120	    continue;
121	  }
122	  try {
123	    await runAttempt(id);
124	  } catch (e) {
125	    // The job stays running here and is recovered on the next worker start.
126	    console.error(`job ${id} failed unexpectedly:`, e);
127	  }
128	}
129	
130	clearInterval(heartbeat);
131	writeHeartbeatSafely(0);
132	db.close();
133	console.log('worker stopped');
134	process.exit(0);
