/** Runs `fn` inside BEGIN IMMEDIATE ... COMMIT, rolling back if it throws. Never awaits inside. */
function inTransaction<T>(fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const value = fn();
    db.exec('COMMIT');
    return value;
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction was already closed by the failure
    }
    throw e;
  }
}

