function claimNext(): string | undefined {
  return inTransaction(() => {
    const row = stmts.nextQueued.get(Date.now()) as { id: string } | undefined;
    if (!row) return undefined;
    stmts.claim.run(nowIso(), row.id);
    return row.id;
  });
}

function requeue(id: string): void {
  stmts.requeue.run(Date.now(), nowIso(), id);
}

/** Processes one attempt of a job. Each step takes STEP_MS; progress is written after each step. */
async function runAttempt(id: string): Promise<void> {
  const job = stmts.byId.get(id) as unknown as JobRow;
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return requeue(id);
    if (attempt >= MAX_ATTEMPTS) {
      stmts.fail.run(nowIso(), id);
    } else {
      stmts.requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return requeue(id);
    stmts.progress.run(step, nowIso(), id);
  }
  stmts.complete.run(job.input.toUpperCase(), nowIso(), id);
}

