  try {
    writeHeartbeat(db, lastSeen);
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}

// Only one worker runs, so any row still marked running was orphaned by a previous crash.
const recovered = stmts.recover.run(Date.now(), nowIso());
if (recovered.changes > 0) console.log(`recovered ${recovered.changes} interrupted job(s)`);

writeHeartbeatSafely();
const heartbeat = setInterval(() => writeHeartbeatSafely(), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  let id: string | undefined;
  try {
    id = claimNext();
  } catch (e) {
    console.error('claim failed:', e);
    await sleep(IDLE_POLL_MS);
    continue;
  }
  if (id === undefined) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  try {
    await runAttempt(id);
  } catch (e) {
    // The job stays running here and is recovered on the next worker start.
    console.error(`job ${id} failed unexpectedly:`, e);
  }
}

